// Access the body from the first webhook event
const body = webhookData?.[0]?.body;

// Extract inserted orders, defaulting to empty array if not found
const insertedOrders = body?.Inserted[0] || [];

// Return the inserted orders as-is (OrderNbr, Date, LineTotal, OpportunityID)
return insertedOrders;

