// Convert datetime string to epoch milliseconds (midnight UTC)
function toEpochMs(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  const normalized = new Date(d.toISOString().split('T')[0] + 'T00:00:00.000Z');
  return normalized.getTime();
}

const properties = {
  order_number: payload?.OrderNbr != null ? String(payload.OrderNbr) : null,
  order_date: toEpochMs(payload?.Date),
  order_total: payload?.LineTotal != null ? String(payload.LineTotal) : null,
  order_created: "Yes",
  dealstage: "closedwon"
};

return [{
  dealId,
  properties
}];

